'use client'

import { type ReactElement, useMemo } from 'react'

import type { SerializedIcon } from '../providers/types.js'

import { SerializedIconSvg } from '../components/Icon.js'
import { useIconDefinitions } from '../providers/clientApi.js'

export type IconProviderCatalogClient = {
  getCategoryMap(): Record<string, string[]>
  getCategoryRepresentative(category: string): string
  getIconNames(): readonly string[]
  id: string
  label: string
}

const PAGE_SIZE = 100

function PickerGlyph({
  definition,
  size,
}: {
  definition?: SerializedIcon
  size: number
}): null | ReactElement {
  return definition ? <SerializedIconSvg definition={definition} size={size} strokeWidth={1.5} /> : null
}

export type IconPickerDropdownProps = {
  client: IconProviderCatalogClient
  expandedCategory: null | string
  expandedVariants: string[]
  matchingCategories: string[]
  onCloseVariants: () => void
  onPageChange: (delta: number) => void
  onSelect: (iconName: string) => void
  onToggleExpand: (category: string) => void
  page: number
  paginatedCategories: string[]
  search: string
  selectedValue: string
  totalMatchingIcons: number
  totalPages: number
}

function IconCategoryCell({
  category,
  categoryMap,
  client,
  definitions,
  expandedCategory,
  onSelect,
  onToggleExpand,
  selectedValue,
}: {
  category: string
  categoryMap: Record<string, string[]>
  client: IconProviderCatalogClient
  definitions: Record<string, SerializedIcon>
  expandedCategory: null | string
  onSelect: (iconName: string) => void
  onToggleExpand: (category: string) => void
  selectedValue: string
}): ReactElement {
  const icons = categoryMap[category] ?? []
  const representative = client.getCategoryRepresentative(category)
  const hasVariants = icons.length > 1
  const isExpanded = expandedCategory === category

  return (
    <div className={`category-cell${isExpanded ? ' expanded' : ''}`}>
      <button
        className={`icon-option${selectedValue === representative ? ' selected' : ''}`}
        onClick={() => onSelect(representative)}
        title={`Select "${representative}"`}
        type="button"
      >
        <PickerGlyph definition={definitions[representative]} size={24} />
        <span className="icon-option-name">{category}</span>
      </button>
      {hasVariants && (
        <button
          className={`variant-badge${isExpanded ? ' active' : ''}`}
          onClick={() => onToggleExpand(category)}
          title={isExpanded ? 'Collapse variants' : `${icons.length} variants`}
          type="button"
        >
          {isExpanded ? '▲' : icons.length}
        </button>
      )}
    </div>
  )
}

function IconVariantsPanel({
  category,
  definitions,
  onClose,
  onSelect,
  selectedValue,
  variants,
}: {
  category: string
  definitions: Record<string, SerializedIcon>
  onClose: () => void
  onSelect: (iconName: string) => void
  selectedValue: string
  variants: string[]
}): ReactElement {
  return (
    <div className="variants-panel">
      <div className="variants-panel-header">
        <span className="variants-panel-title">
          <strong>{category}</strong> variants{' '}
          <span className="variants-panel-count">({variants.length})</span>
        </span>
        <button className="variants-close-btn" onClick={onClose} title="Close" type="button">
          ✕
        </button>
      </div>
      <div className="icon-grid">
        {variants.map((iconName) => (
          <button
            className={`icon-option${selectedValue === iconName ? ' selected' : ''}`}
            key={iconName}
            onClick={() => onSelect(iconName)}
            title={iconName}
            type="button"
          >
            <PickerGlyph definition={definitions[iconName]} size={24} />
            <span className="icon-option-name">{iconName}</span>
          </button>
        ))}
      </div>
    </div>
  )
}

export function IconPickerDropdown({
  client,
  expandedCategory,
  expandedVariants,
  matchingCategories,
  onCloseVariants,
  onPageChange,
  onSelect,
  onToggleExpand,
  page,
  paginatedCategories,
  search,
  selectedValue,
  totalMatchingIcons,
  totalPages,
}: IconPickerDropdownProps): ReactElement {
  const categoryMap = useMemo(() => client.getCategoryMap(), [client])
  const visibleNames = useMemo(() => [
    ...paginatedCategories.map((category) => client.getCategoryRepresentative(category)),
    ...expandedVariants,
  ], [client, expandedVariants, paginatedCategories])
  const definitions = useIconDefinitions(client.id, visibleNames, 'regular')

  return (
    <div className="icon-picker-dropdown">
      <div className="dropdown-header">
        <span className="dropdown-count">
          {matchingCategories.length} categories · {totalMatchingIcons} icons
        </span>
        {totalPages > 1 && (
          <div className="pagination">
            <button
              className="page-btn"
              disabled={page === 0}
              onClick={() => onPageChange(-1)}
              type="button"
            >
              ‹
            </button>
            <span className="page-info">
              {page + 1} / {totalPages}
            </span>
            <button
              className="page-btn"
              disabled={page === totalPages - 1}
              onClick={() => onPageChange(1)}
              type="button"
            >
              ›
            </button>
          </div>
        )}
      </div>

      <div className="icon-grid">
        {paginatedCategories.map((category) => (
          <IconCategoryCell
            category={category}
            categoryMap={categoryMap}
            client={client}
            definitions={definitions}
            expandedCategory={expandedCategory}
            key={category}
            onSelect={onSelect}
            onToggleExpand={onToggleExpand}
            selectedValue={selectedValue}
          />
        ))}
      </div>

      {expandedCategory && (
        <IconVariantsPanel
          category={expandedCategory}
          definitions={definitions}
          onClose={onCloseVariants}
          onSelect={onSelect}
          selectedValue={selectedValue}
          variants={expandedVariants}
        />
      )}

      {matchingCategories.length === 0 && (
        <div className="no-results">No icons found matching &quot;{search}&quot;</div>
      )}
    </div>
  )
}

export function useIconPickerSearch(client: IconProviderCatalogClient, search: string) {
  return useMemo(() => {
    const categoryMap = client.getCategoryMap()
    const allCategoryKeys = Object.keys(categoryMap).sort()
    const allIconNames = client.getIconNames()

    if (!search) {
      return {
        matchingCategories: allCategoryKeys,
        totalMatchingIcons: allIconNames.length,
      }
    }

    const lower = search.toLowerCase()
    let totalMatchingIcons = 0
    const matchingCategories = Object.entries(categoryMap)
      .filter(([, iconNames]) => {
        const matchCount = iconNames.filter((name) => name.toLowerCase().includes(lower)).length
        totalMatchingIcons += matchCount
        return matchCount > 0
      })
      .map(([category]) => category)
      .sort()

    return { matchingCategories, totalMatchingIcons }
  }, [client, search])
}

export { PAGE_SIZE }
